import React, { useState, useEffect, useContext } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import GameClient from '../services/GameClient';
import { GameClientContext } from '../contexts/GameClientContext';
import { useGameLogic } from '../hooks/useGameLogic';
import { useGameExit } from '../hooks/useGameExit';
import { useTimer } from '../hooks/useTimer';

import { TimerComponent } from './TimerComponent';


import {
    NumberButton,
    QuitButton,
    OperatorButton,
    ControlButton,
    NumbersGrid,
    OperatorGrid,
    ButtonGroup,
} from '../components/GameButtons';

import {
    Container,
    Header,
    HeaderRow,
    Title,
    RightControls,
    TimerWrapper,
    GameAreaSingle,
    CurrentPlayerAreaSingle,
    FormulaDisplay,
    ResultDisplay,
    WinnerDisplay,
    WinnerFormula,
    PlayerName,
    GameTimer
} from '../components/GameStyles';



const GamePageSingle: React.FC = () => {
    console.log("GamePageSingle re-rendered at", new Date().toISOString());
    const {
        client,
        playerName,
        formula,
        result,
        gameNumbers,
        winner,
        winnerFormula,
        isTimerRunning,
        usedButtonIndices,
        handleNumberTokenClick,
        handleTokenClick,
        handleRemove,
        handleClear,
        handleNewGame,
        handleLogout,

    } = useGameLogic();

    const navigate = useNavigate();

    //const gameTime = useTimer(isCountingDown, winner);


    useGameExit(client);

    return (
        <Container>
                <>
                    <Header>
                        <HeaderRow>
                            <Title>24 Game - Singleplayer</Title>
                        </HeaderRow>
                        <HeaderRow>
                            <PlayerName>Player: {playerName}</PlayerName>
                            <RightControls>
                                <TimerWrapper>
                                    <TimerComponent isRunning={isTimerRunning}/>
                                </TimerWrapper>
                                <QuitButton onClick = {handleLogout}>Quit Game</QuitButton>
                            </RightControls>
                        </HeaderRow>
                    </Header>

                    {winner && (
                        <WinnerDisplay>
                            <h2>Game Solved!</h2>
                            <div>Winner: {winner}</div>
                            <WinnerFormula>
                                Winning Solution: {winnerFormula}
                            </WinnerFormula>
                            <div>Time: test4</div>
                        </WinnerDisplay>
                    )}

                    <GameAreaSingle>
                        <CurrentPlayerAreaSingle>
                            <NumbersGrid>
                                {gameNumbers.map((num, index) => (
                                    <NumberButton 
                                    key={index} 
                                    onClick={() => handleNumberTokenClick(num, index)}
                                    disabled={usedButtonIndices.includes(index)}
                                    style={{
                                        backgroundColor: usedButtonIndices.includes(index) ? '#e0e0e0' : 'white',
                                        color: usedButtonIndices.includes(index) ? '#999' : '#333',
                                        cursor: usedButtonIndices.includes(index) ? 'not-allowed' : 'pointer'
                                    }}
                                    >
                                    {num}
                                    </NumberButton>
                                ))
                            }

                            </NumbersGrid>

                            <FormulaDisplay>
                                {formula || 'Start building your formula'}
                            </FormulaDisplay>

                            <ResultDisplay>
                                Result: {result}
                            </ResultDisplay>

                            <OperatorGrid>
                                {['+', '-', '*', '/', '(', ')'].map((op) => (
                                    <OperatorButton 
                                        key={op} 
                                        onClick={() => handleTokenClick(op)}
                                    >
                                        {op}
                                    </OperatorButton>
                                ))}
                            </OperatorGrid>

                            <ButtonGroup>
                                <ControlButton onClick={handleClear}>
                                    Clear
                                </ControlButton>
                                <ControlButton onClick={handleRemove}>
                                    Undo
                                </ControlButton>
                                <ControlButton onClick={handleNewGame}>
                                    New Game
                                </ControlButton>
                            </ButtonGroup>
                        </CurrentPlayerAreaSingle>
                    </GameAreaSingle>
                </>

        </Container>
    );
};

export default GamePageSingle;
